import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar';
import MapComponent from './components/MapComponent';
import RentPredictor from './components/rent-predictor/RentPredictor';
import Login from './components/Login'; 
import PropertyList from './components/PropertyList';
import AiMatchmaker from './components/AiMatchmaker';

const Home = () => (
  <div style={{ padding: "20px", fontFamily: "sans-serif", maxWidth: "1200px", margin: "0 auto" }}>

    {/* Clean & Premium Header */}
    <div style={{ textAlign: "center", padding: "40px 0 20px 0" }}>
      <h1 style={{ color: "#4a3b52", fontSize: "2.8rem", margin: "0 0 10px 0" }}>
        Find Your Perfect Student Stay
      </h1>
      <p style={{ color: "#786d84", fontSize: "1.2rem", margin: 0 }}>
        AI-powered PG & Hostel recommendations tailored for you
      </p>
    </div>

    {/* AI Matchmaker Premium Banner */}
    <div style={{
      background: "linear-gradient(135deg, #80608f 0%, #4a3b52 100%)",
      borderRadius: "16px",
      padding: "30px 40px",
      color: "white",
      marginBottom: "40px",
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
      flexWrap: "wrap",
      gap: "20px",
      boxShadow: "0 10px 25px rgba(128, 96, 143, 0.2)"
    }}>
      <div>
        <h2 style={{ margin: "0 0 10px 0", fontSize: "1.8rem" }}>✨ AI Matchmaker</h2>
        <p style={{ margin: 0, opacity: 0.9, fontSize: "1.1rem" }}>
          Tell us your budget and needs, and let our AI find the best PGs near MIET for you.
        </p>
      </div>
      <button style={{
        padding: "14px 28px",
        fontSize: "1.1rem",
        backgroundColor: "white",
        color: "#4a3b52",
        border: "none",
        borderRadius: "8px",
        fontWeight: "bold",
        cursor: "pointer",
        boxShadow: "0 4px 6px rgba(0,0,0,0.1)"
      }}>
        Find My Match
      </button>
    </div>

    {/* Original Rent Predictor (Isko ab poori jagah milegi) */}
    <div style={{ marginBottom: "50px" }}>
       <h3 style={{ color: "#80608f", textAlign: "center", marginBottom: "20px", fontSize: "1.5rem" }}>
         📈 Rent Predictor
       </h3>
       <RentPredictor />
    </div>

    <hr style={{ margin: "40px 0", border: "1px solid #e6d9ef" }} />

    {/* Properties List Component */}
    <PropertyList />

    <hr style={{ margin: "40px 0", border: "1px solid #e6d9ef" }} />

    {/* Map Section */}
    <h3 style={{ color: "#80608f", textAlign: "center", fontSize: "2rem", marginBottom: "20px" }}>
      Explore Campus Vicinity
    </h3>
    <MapComponent 
      lat={28.9731} 
      lng={77.6402} 
      pgName="MIET College Area" 
      rent={0} 
    />
  </div>
);

function App() {
  return (
    <Router>
      <div style={{ backgroundColor: "#faf8fc", minHeight: "100vh" }}>
        <Navbar />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/login" element={<Login />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
